create table if not exists processing_jobs(id uuid primary key default gen_random_uuid(),user_id uuid default auth.uid(),source_path text not null,title text,status text not null default 'queued',rights_confirmed boolean not null default false,duration_seconds numeric,created_at timestamptz default now());create table if not exists transcripts(id uuid primary key default gen_random_uuid(),job_id uuid references processing_jobs(id) on delete cascade,text text not null,words jsonb default '[]',created_at timestamptz default now());create table if not exists clip_candidates(id uuid primary key default gen_random_uuid(),job_id uuid references processing_jobs(id) on delete cascade,title text not null,hook text,start_seconds numeric not null,end_seconds numeric not null,reason text,scores jsonb not null,predicted_engagement_score integer not null,output_path text,thumbnail_path text,review_status text not null default 'pending' check(review_status in('pending','approved','rejected','revision_requested')),editor_notes text,created_at timestamptz default now());alter table processing_jobs enable row level security;alter table transcripts enable row level security;alter table clip_candidates enable row level security;create policy "owners manage jobs" on processing_jobs for all using(user_id=auth.uid()) with check(user_id=auth.uid());